package com.example.homefitness

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore

class OnboardingActivity : AppCompatActivity() {
    private val db=FirebaseFirestore.getInstance(); private val auth=FirebaseAuth.getInstance()
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContentView(R.layout.activity_onboarding);findViewById<android.view.View>(R.id.saveOnboardingButton).setOnClickListener{saveAnswers()};loadExistingAnswers()}
    private fun loadExistingAnswers(){val uid=auth.currentUser?.uid?:return;db.collection("users").document(uid).get().addOnSuccessListener{d->if(!d.exists())return@addOnSuccessListener;fun setSpinner(id:Int,values:List<String>,field:String){val value=d.getString(field)?:return;val index=values.indexOf(value);if(index>=0)findViewById<android.widget.Spinner>(id).setSelection(index)};setSpinner(R.id.goalSpinner,listOf("general_fitness","weight_loss","build_muscle","endurance"),"fitnessGoal");setSpinner(R.id.experienceSpinner,listOf("beginner","intermediate","advanced"),"experienceLevel");setSpinner(R.id.equipmentSpinner,listOf("none","home","gym"),"equipment");setSpinner(R.id.dietSpinner,listOf("none","vegetarian","vegan","pescatarian","halal","kosher"),"dietPreference");d.getLong("workoutDaysPerWeek")?.let{findViewById<android.widget.Spinner>(R.id.daysSpinner).setSelection((it.toInt()-1).coerceIn(0,6))};d.getLong("workoutMinutes")?.let{v->val values=listOf(15,20,30,45,60,90);val i=values.indexOf(v.toInt());if(i>=0)findViewById<android.widget.Spinner>(R.id.minutesSpinner).setSelection(i)};findViewById<android.widget.EditText>(R.id.allergiesInput).setText(d.getString("foodAllergies")?:"");findViewById<android.widget.EditText>(R.id.ageInput).setText(d.getLong("age")?.toString()?:"");findViewById<android.widget.EditText>(R.id.heightInput).setText(d.getDouble("heightCm")?.toString()?:"");findViewById<android.widget.EditText>(R.id.weightInput).setText(d.getDouble("weight")?.toString()?:"")}}
    private fun saveAnswers(){val uid=auth.currentUser?.uid?:run{finish();return};val goal=listOf("general_fitness","weight_loss","build_muscle","endurance")[findViewById<android.widget.Spinner>(R.id.goalSpinner).selectedItemPosition];val experience=listOf("beginner","intermediate","advanced")[findViewById<android.widget.Spinner>(R.id.experienceSpinner).selectedItemPosition];val equipment=listOf("none","home","gym")[findViewById<android.widget.Spinner>(R.id.equipmentSpinner).selectedItemPosition];val days=findViewById<android.widget.Spinner>(R.id.daysSpinner).selectedItem.toString().toIntOrNull()?:3;val minutes=findViewById<android.widget.Spinner>(R.id.minutesSpinner).selectedItem.toString().toIntOrNull()?:30;val diet=listOf("none","vegetarian","vegan","pescatarian","halal","kosher")[findViewById<android.widget.Spinner>(R.id.dietSpinner).selectedItemPosition];val allergies=findViewById<android.widget.EditText>(R.id.allergiesInput).text.toString().trim();val age=findViewById<android.widget.EditText>(R.id.ageInput).text.toString().toIntOrNull();val height=findViewById<android.widget.EditText>(R.id.heightInput).text.toString().toDoubleOrNull();val weight=findViewById<android.widget.EditText>(R.id.weightInput).text.toString().toDoubleOrNull();val user=auth.currentUser;val data=hashMapOf<String,Any>("name" to (user?.displayName?:user?.email?.substringBefore("@")?:"User"),"email" to (user?.email?:""),"calorieGoal" to 2000,"caloriesConsumed" to 0,"mealsCalories" to 0,"streak" to 0,"fitnessGoal" to goal,"experienceLevel" to experience,"equipment" to equipment,"workoutDaysPerWeek" to days,"workoutMinutes" to minutes,"dietPreference" to diet,"foodAllergies" to allergies,"onboardingCompleted" to true,"updatedAt" to com.google.firebase.firestore.FieldValue.serverTimestamp());age?.let{data["age"]=it};height?.let{data["heightCm"]=it};weight?.let{data["weight"]=it};db.collection("users").document(uid).set(data,com.google.firebase.firestore.SetOptions.merge()).addOnSuccessListener{Toast.makeText(this,"Preferences saved",Toast.LENGTH_SHORT).show();startActivity(Intent(this,HomeActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK));finish()}.addOnFailureListener{Toast.makeText(this,"Could not save preferences: ${it.localizedMessage}",Toast.LENGTH_LONG).show()}}
}
